SELECT CASE WHEN duration_sec >= 510 THEN 'HIGH' ELSE 'LOW' END AS duration_sec_tier, COUNT_IF(event_type = 'click') AS click_events, PERCENTILE_APPROX(duration_sec, ARRAY(0.25, 0.5, 0.75)) AS duration_sec_quartiles, SUM(duration_sec) FILTER (WHERE event_type = 'page_view') AS page_view_total_duration_sec, ROUND(SUM(duration_sec) / NULLIF(COUNT(CASE WHEN event_type = 'page_view' THEN 1 END), 0), 2) AS duration_sec_per_page_view FROM web_events GROUP BY CASE WHEN duration_sec >= 510 THEN 'HIGH' ELSE 'LOW' END
